function finalize(){state.nextOperation=result.operation;return result;}
const response=$context.$nodes.XDX_READ_SUPPLIER.$output;
const state=JSON.parse(JSON.stringify($context.$variables.supplierState));
const pending=state.pending||{};
const result={operation:'display',state:state};
function stop(message){state.response={message:message};return finalize();}
if(!response || typeof response.SupplierId!=='number' || !Number.isSafeInteger(response.SupplierId) || response.SupplierId<=0 || String(response.SupplierId)!==pending.suppliers_Id || typeof response.Supplier!=='string' || typeof response.SupplierNumber!=='string' || typeof response.Status!=='string')return stop('The supplier detail could not be verified. The draft was not changed.');
if(pending.purpose!=='template' && response.Status!=='ACTIVE' && pending.includeInactive!==true)return stop('This supplier is inactive. Ask explicitly to view inactive suppliers.');
state.selection=JSON.parse(JSON.stringify(response));
if(pending.purpose==='child_create'){result.operation='child_prepare';return finalize();}
if(pending.purpose==='children'){result.operation='children';return finalize();}
if(pending.purpose==='site_template'){result.operation='site_template';return finalize();}
state.activeRead='suppliers';
if(pending.purpose!=='template'){state.response={message:'Supplier details.',supplier:state.selection};return finalize();}
if(['ACTIVE','INACTIVE'].indexOf(response.Status)<0)return stop('The source supplier status could not be verified.');
if(state.draft)return stop('A draft already exists. Edit or cancel it before starting another.');
const fields=['SupplierType','BusinessRelationship','TaxOrganizationType'];
const missing=fields.filter(function(k){return typeof response[k]!=='string' || !response[k].trim() || response[k].length>80;});
const conversation=$context.$workflow && $context.$workflow.$conversationId;
const sequence=state.nextRequestSequence;
const requestId='REQ-'+conversation+'-'+sequence;
if(typeof conversation!=='string' || !/^[A-Za-z0-9_-]+$/.test(conversation) || requestId.length>96 || !Number.isSafeInteger(sequence) || sequence<1 || sequence>=9007199254740991)return stop('A unique draft request could not be initialized. Nothing was created.');
const name=typeof pending.newName==='string'?pending.newName:'';
if(name.length>360)return stop('The new supplier name must be at most 360 characters.');
const draft={kind:'supplier',requestId:requestId,revision:1,status:'editing',source:JSON.parse(JSON.stringify(response)),payload:{Supplier:name,SupplierType:missing.indexOf('SupplierType')<0?response.SupplierType:null,BusinessRelationship:response.BusinessRelationship,TaxOrganizationType:response.TaxOrganizationType},classificationsVerified:missing.length===0};
state.nextRequestSequence=sequence+1;state.draft=draft;
state.response={message:missing.length?'Choose values for '+missing.join(', ')+'. The new supplier remains a draft.':'Review the inherited classifications and enter the new supplier name.',requestId:draft.requestId,revision:1,payload:draft.payload,source:draft.source};
if(missing.length || !name.trim())return finalize();
state.pending={purpose:'duplicate',q:"Supplier='"+name.replace(/'/g,"''")+"'",limit:1,offset:0,requestId:draft.requestId,revision:draft.revision,name:name};result.operation='duplicate';return finalize();
